<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Computer Languages Quiz</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --card: #ffffff;
      --text: #122033;
      --muted: #5f6b7a;
      --border: #d9e2ec;
      --accent: #2563eb;
      --accent-soft: #e8f0ff;
      --success: #0f766e;
      --shadow: 0 20px 50px rgba(18, 32, 51, 0.08);
      --radius: 18px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, #e9f1ff 0%, transparent 35%),
        linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
      color: var(--text);
      min-height: 100vh;
      padding: 32px 16px;
    }

    .quiz-shell {
      max-width: 760px;
      margin: 0 auto;
      background: var(--card);
      border: 1px solid rgba(217, 226, 236, 0.8);
      border-radius: 28px;
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .quiz-header {
      padding: 32px 32px 12px;
      border-bottom: 1px solid var(--border);
    }

    .eyebrow {
      margin: 0 0 8px;
      color: var(--accent);
      font-size: 0.85rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 3vw, 2.75rem);
      line-height: 1.1;
    }

    .subtitle {
      margin: 12px 0 0;
      color: var(--muted);
      max-width: 58ch;
    }

    form {
      padding: 24px 32px 32px;
    }

    .form-field {
      padding: 20px;
      margin-bottom: 18px;
      border: 1px solid var(--border);
      border-radius: var(--radius);
      background: linear-gradient(180deg, #ffffff 0%, #fbfdff 100%);
    }

    .question-title {
      margin: 0 0 8px;
      font-size: 1.05rem;
    }

    .help-text {
      margin: 0 0 14px;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .choices {
      display: grid;
      gap: 10px;
    }

    .choice {
      display: flex;
      align-items: flex-start;
      gap: 12px;
      padding: 12px 14px;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: #fff;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
      cursor: pointer;
    }

    .choice:hover {
      border-color: #b9ccf7;
      box-shadow: 0 8px 18px rgba(37, 99, 235, 0.08);
      transform: translateY(-1px);
    }

    .choice input {
      margin-top: 3px;
      width: 18px;
      height: 18px;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    .choice span {
      display: block;
      line-height: 1.4;
    }

    .actions {
      display: flex;
      align-items: center;
      gap: 16px;
      margin-top: 22px;
      flex-wrap: wrap;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      background: var(--accent);
      color: white;
      font: inherit;
      font-weight: 700;
      padding: 14px 22px;
      cursor: pointer;
      box-shadow: 0 12px 24px rgba(37, 99, 235, 0.22);
      transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
    }

    button:hover {
      background: #1d4ed8;
      transform: translateY(-1px);
      box-shadow: 0 14px 28px rgba(37, 99, 235, 0.26);
    }

    button:focus-visible,
    .choice input:focus-visible {
      outline: 3px solid #93c5fd;
      outline-offset: 2px;
    }

    .result {
      min-height: 1.5em;
      color: var(--success);
      font-weight: 600;
    }

    @media (max-width: 640px) {
      body {
        padding: 12px;
      }

      .quiz-header,
      form {
        padding-left: 18px;
        padding-right: 18px;
      }

      .form-field {
        padding: 16px;
      }
    }
  </style>
</head>
<body>
  <main class="quiz-shell">
    <header class="quiz-header">
      <p class="eyebrow">Knowledge check</p>
      <h1>Computer Languages Quiz</h1>
      <p class="subtitle">Select all answers that apply for each question, then submit your responses.</p>
    </header>

    <form id="quiz-form">
      <div class="form-field">
        <h2 class="question-title">1. Which of these are programming languages?</h2>
        <p class="help-text" id="q1-help">This question may have more than one correct answer.</p>
        <div class="choices" aria-describedby="q1-help">
          <label class="choice"><input type="checkbox" name="q1" value="python" /> <span>Python</span></label>
          <label class="choice"><input type="checkbox" name="q1" value="html" /> <span>HTML</span></label>
          <label class="choice"><input type="checkbox" name="q1" value="javascript" /> <span>JavaScript</span></label>
          <label class="choice"><input type="checkbox" name="q1" value="sql" /> <span>SQL</span></label>
        </div>
      </div>

      <div class="form-field">
        <h2 class="question-title">2. Which languages are commonly used for web development?</h2>
        <div class="choices">
          <label class="choice"><input type="checkbox" name="q2" value="javascript" /> <span>JavaScript</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="css" /> <span>CSS</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="rust" /> <span>Rust</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="html" /> <span>HTML</span></label>
        </div>
      </div>

      <div class="form-field">
        <h2 class="question-title">3. Which of these are compiled or interpreted programming languages?</h2>
        <div class="choices">
          <label class="choice"><input type="checkbox" name="q3" value="csharp" /> <span>C#</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="python" /> <span>Python</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="markdown" /> <span>Markdown</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="go" /> <span>Go</span></label>
        </div>
      </div>

      <div class="actions">
        <button type="submit">Submit quiz</button>
        <div class="result" id="result" aria-live="polite"></div>
      </div>
    </form>
  </main>

  <script>
    const answers = {
      q1: ['python', 'javascript', 'sql'],
      q2: ['javascript', 'css', 'html'],
      q3: ['csharp', 'python', 'go']
    };

    const form = document.getElementById('quiz-form');
    const result = document.getElementById('result');

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      let correctCount = 0;
      const total = Object.keys(answers).length;

      for (const [question, expected] of Object.entries(answers)) {
        const selected = [...form.querySelectorAll(`input[name="${question}"]:checked`)].map((input) => input.value).sort();
        const expectedSorted = [...expected].sort();
        const isCorrect = selected.length === expectedSorted.length && selected.every((value, index) => value === expectedSorted[index]);

        if (isCorrect) {
          correctCount += 1;
        }
      }

      result.textContent = `You got ${correctCount} out of ${total} questions correct.`;
    });
  </script>
</body>
</html>
